import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"ADR-0003: Peer Enrollment Approval Gate and Client-Side Key Generation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0003-peer-enrollment-approval-and-client-side-keygen.md","filePath":"adr/0003-peer-enrollment-approval-and-client-side-keygen.md"}'),n={name:"adr/0003-peer-enrollment-approval-and-client-side-keygen.md"};function i(s,e,l,d,p,c){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="adr-0003-peer-enrollment-approval-gate-and-client-side-key-generation" tabindex="-1">ADR-0003: Peer Enrollment Approval Gate and Client-Side Key Generation <a class="header-anchor" href="#adr-0003-peer-enrollment-approval-gate-and-client-side-key-generation" aria-label="Permalink to &quot;ADR-0003: Peer Enrollment Approval Gate and Client-Side Key Generation&quot;">​</a></h1><ul><li><strong>Status</strong>: Adopted (standalone path, Release-N scope — client keygen + opt-in approval gate, API + CLI; K8s CRD path, dashboard UI and audit actor wiring remain follow-ups)</li><li><strong>Date</strong>: 2026-09-17</li><li><strong>Related</strong>: ADR-0004 (LRP per-peer authentication — transport plane), 2026-09-17 codebase review (docs/reviews/2026-09-17-codebase-review.md)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><h3 id="today-s-admission-flow" tabindex="-1">Today&#39;s admission flow <a class="header-anchor" href="#today-s-admission-flow" aria-label="Permalink to &quot;Today&#39;s admission flow&quot;">​</a></h3><p>Enrollment is already gated by <strong>Enrollment Tokens</strong> (single-use, TTL, usage limit — <code>t_enrollment_tokens</code>, <code>EnrollmentTokens()</code> store; LatticePeer + AgentIdentity auto-created on the K8s path). But presenting a valid token is sufficient: the peer is admitted immediately, with no approval step and no human in the loop. Whoever obtains a token (they are shared with device owners by copy/paste) can enroll an arbitrary device into the workspace.</p><p>There is no lifecycle state on a peer beyond liveness: <code>models/peer.go</code> has no pending/approved/revoked status, and the netmap builder admits every registered peer unconditionally.</p><h3 id="the-deeper-gap-server-side-key-generation" tabindex="-1">The deeper gap: server-side key generation <a class="header-anchor" href="#the-deeper-gap-server-side-key-generation" aria-label="Permalink to &quot;The deeper gap: server-side key generation&quot;">​</a></h3><p>The two enrollment paths disagree about who owns the WireGuard keypair:</p><ul><li><strong>Sandbox HTTP enroll</strong> (<code>agent_registration.go</code>): the agent generates the keypair locally and submits only the public key (<code>// PublicKey is the WireGuard public key generated by the Agent</code>).</li><li><strong>Regular <code>lattice up</code> registration</strong> (NATS <code>register</code> → <code>peerService.registerStandalone</code>, <code>peer.go:479-516</code>): the control plane generates the private key on first enrollment, stores it in <code>t_peer</code>, and <strong>returns it to the agent</strong> inside <code>infra.Peer.PrivateKey</code>.</li></ul><p>Consequences of the server-side path:</p><ol><li>A database leak leaks every peer&#39;s private key — the entire mesh&#39;s identity material at once.</li><li>The control plane can impersonate any peer (it holds every private key), which weakens the meaning of peer identity everywhere else, including the relay authentication design in ADR-0004.</li><li>Private keys traverse the wire twice in plaintext contexts (NATS JSON signal payloads at registration, DB at rest), contradicting the zero-trust positioning of the product.</li></ol><p>The two paths should converge on client-side key generation. Because the approval gate and the key-hand-off touch the same registration code path, they are designed together in this ADR.</p><h3 id="existing-precedent" tabindex="-1">Existing precedent <a class="header-anchor" href="#existing-precedent" aria-label="Permalink to &quot;Existing precedent&quot;">​</a></h3><p>The policy layer already implements a review workflow with audit: <code>PolicyStatusPending → PolicyStatusApproved</code> (<code>models/policy.go</code>) and <code>policy_version.go</code> records &quot;who changed it, who approved it&quot;. The approval gate proposed here reuses that pattern rather than inventing a new one.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Approval gate</strong>: a peer becomes network-reachable only after explicit approval. Lifecycle: <code>pending → approved</code>, plus <code>revoked</code> (and <code>expired</code> for TTL scenarios). Unapproved peers exist in the registry (so they show up in the dashboard and can be approved) but receive an empty netmap and are excluded from every other peer&#39;s netmap.</li><li><strong>Client-side key generation on every path</strong>: the agent always generates its WireGuard keypair locally and submits only the public key. The control plane stores public keys only; <code>infra.Peer.PrivateKey</code> is removed from the wire struct. A one-release compatibility window accepts legacy agents that arrive without a public key (server keeps generating for them, with a loud warning).</li><li><strong>Re-registration binds to (AppID, PublicKey)</strong>: an existing AppID re-registering with a <em>different</em> public key is treated as a new device — it re-enters <code>pending</code> (or is rejected, per workspace policy) instead of silently taking over the old identity. Same key resumes as today.</li></ol><h2 id="detailed-design" tabindex="-1">Detailed design <a class="header-anchor" href="#detailed-design" aria-label="Permalink to &quot;Detailed design&quot;">​</a></h2><h3 id="peer-lifecycle-state-machine" tabindex="-1">Peer lifecycle state machine <a class="header-anchor" href="#peer-lifecycle-state-machine" aria-label="Permalink to &quot;Peer lifecycle state machine&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             token valid</span></span>
<span class="line"><span>  (absent) ───────────────► pending ──approve──► approved ──revoke──► revoked</span></span>
<span class="line"><span>                              │  ▲                    │</span></span>
<span class="line"><span>                              │  └─ re-register,</span></span>
<span class="line"><span>                              │     same pubkey      │ re-register,</span></span>
<span class="line"><span>                              ▼                       ▼ different pubkey → pending</span></span>
<span class="line"><span>                          (heartbeat wait)         approved (new state recorded)</span></span></code></pre></div><p>New columns on <code>t_peer</code> (and status condition on LatticePeer CRD):</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>ApprovalStatus</td><td>string</td><td><code>pending</code> / <code>approved</code> / <code>revoked</code>; default <code>approved</code> for compatibility (see Rollout)</td></tr><tr><td>ApprovedBy</td><td>string</td><td>user identity of the approver</td></tr><tr><td>ApprovedAt</td><td>time</td><td></td></tr></tbody></table><p>The default of <code>approved</code> is deliberate: approval is <strong>opt-in per workspace</strong> (<code>Workspace.RequirePeerApproval bool</code>, default false), so single-user / homelab deployments (the community majority) see zero behavior change until they flip the switch. Enterprises set it per workspace.</p><h3 id="registration-with-a-pending-peer" tabindex="-1">Registration with a pending peer <a class="header-anchor" href="#registration-with-a-pending-peer" aria-label="Permalink to &quot;Registration with a pending peer&quot;">​</a></h3><ul><li><code>registerStandalone</code> / K8s register succeed (token validated, peer row created) but the response carries <code>ApprovalStatus: &quot;pending&quot;</code>, <strong>no overlay address and no netmap</strong>.</li><li>The agent prints a first-class status — <code>awaiting approval from the workspace administrator</code> — and polls <code>GetNetmap</code> on a slow backoff (30s → 5min cap). Heartbeats continue so the peer shows as &quot;pending, seen 12s ago&quot; in the dashboard rather than as a ghost.</li><li>When approved, the control plane publishes <code>PublishNetmapChanged</code> for the new peer; its next refresh assigns the address and it converges like any other join (no re-registration needed).</li><li>The netmap builders (both <code>reconcilers.NetmapBuilder</code> and the K8s ConfigMap path) skip peers whose approval status is not <code>approved</code>.</li></ul><h3 id="approval-ux" tabindex="-1">Approval UX <a class="header-anchor" href="#approval-ux" aria-label="Permalink to &quot;Approval UX&quot;">​</a></h3><ul><li>Dashboard: peer list gains status badges with approve/reject actions (RBAC-gated, same permission model as workspace admin).</li><li>CLI: <code>lattice peer approve &lt;app-id&gt;</code>, <code>lattice peer reject &lt;app-id&gt;</code>.</li><li>API: <code>POST /api/v1/workspaces/{ws}/peers/{app-id}/approval</code> with <code>{ &quot;status&quot;: &quot;approved&quot; | &quot;revoked&quot; }</code>.</li><li>Every transition writes an audit record (pattern: <code>policy_version.go</code>) with actor, timestamp, and reason (reason optional).</li></ul><h3 id="client-side-key-generation" tabindex="-1">Client-side key generation <a class="header-anchor" href="#client-side-key-generation" aria-label="Permalink to &quot;Client-side key generation&quot;">​</a></h3><ul><li>Agent (<code>internal/agent</code>): before <code>ctrClient.Register</code>, generate <code>wgtypes.GeneratePrivateKey()</code> locally, include <code>dto.PeerDto.PublicKey</code> in the register request, and <strong>ignore</strong> any <code>PrivateKey</code> present in the response (defense in depth during the compat window). The generated private key never leaves the process; it persists in the local store so re-registration presents the same key.</li><li>Control plane: on requests carrying <code>PublicKey</code>, store it and never generate. <code>infra.Peer.PrivateKey</code> field removal from the wire struct is the final step of the rollout; the compat shim reads the legacy field only when the request lacked a public key.</li><li>Key rotation: user-initiated via <code>lattice rotate-keys</code> (regenerates locally, re-registers with the same AppID + new public key). With the binding rule in Decision 3, rotation of an approved peer re-enters <code>pending</code> if the workspace requires approval — documented behavior, matching Tailscale&#39;s re-approval semantics for new keys.</li></ul><h2 id="rollout" tabindex="-1">Rollout <a class="header-anchor" href="#rollout" aria-label="Permalink to &quot;Rollout&quot;">​</a></h2><ol><li><strong>Release N</strong> — client keygen + server compat shim (both registration paths converge; wire still tolerates legacy agents).</li><li><strong>Release N</strong> — approval state machine with per-workspace opt-in (<code>RequirePeerApproval=false</code> default), dashboard/CLI/API, netmap gating.</li><li><strong>Release N+1</strong> — flip K8s/standalone defaults for <em>new</em> workspaces to <code>RequirePeerApproval=true</code>; drop <code>infra.Peer.PrivateKey</code> from the wire struct; server-side keygen code deleted.</li></ol><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Approval gate only, keep server-side keygen</strong> — rejected: it fixes the cheaper half while leaving the identity root of trust on the server; the two changes share the registration path, so deferring keygen means paying the migration twice.</li><li><strong>Admission via mTLS device certificates</strong> — heavier infrastructure (CA, rotation, revocation) than the problem needs at this stage; revisit if device-posture requirements arrive.</li><li><strong>No approval, rely on short-lived tokens only</strong> — rejected: does not cover leaked or socially-engineered tokens, and provides no audit trail for compliance-oriented users.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Token possession becomes * candidacy, not admission*: a leaked token surfaces as a visible pending peer instead of a silent network join.</li><li>The control plane database no longer contains any private key material.</li><li>Admin overhead grows for workspaces that enable approval — mitigated by opt-in default and by auto-approve remaining available.</li><li>ADR-0004&#39;s relay identity proof becomes <em>stronger</em> once keygen is client-side: the relay challenge-response then proves possession of a secret the control plane itself never had.</li></ul><h2 id="non-goals-future-work" tabindex="-1">Non-goals / future work <a class="header-anchor" href="#non-goals-future-work" aria-label="Permalink to &quot;Non-goals / future work&quot;">​</a></h2><ul><li>QUIC relay <code>InsecureSkipVerify</code> → certificate fingerprint pinned via the control plane (TOFU) — separate small ADR.</li><li>Rate limiting of relay forwarding per member (internal DoS).</li><li>Device posture checks (OS version, disk encryption) as approval inputs.</li></ul>`,36)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
